%% Base parameters of the UR5e from nothing but its MDH table
%
% Step 1  the geometry (robots/mdh_ur5e.m) is the only input; no inertial value is known or assumed
% Step 2  base_parameters_from_mdh finds the identifiable combinations (the base parameters) and certifies them
% Step 3  numerical values of the base parameters, from standard parameters (CAD) if you have them
% Step 4  numerical values of the base parameters from measured data (least squares)
%
% Step 4 is run here on data generated by the independent Newton-Euler reference with the nominal parameters,
% so the identified values can be compared with the true ones. Replace q, qd, qdd, y by your measurements
% (in the MDH convention, see the note at Step 4) to identify a real robot.
%
% Variants: 'known' = rigid body, link dimensions known (36 base parameters);
%           'actuation_known' = rigid body + rotor inertia + viscous and Coulomb friction (52 base parameters).
variant = 'known';                       % or 'actuation_known'

here = fileparts(mfilename('fullpath'));  root = fileparts(here);
addpath(fullfile(root, 'mdh'), fullfile(root, 'core'), fullfile(root, 'robots'));
folder_of = struct('known', 'known_geometry', 'actuation_known', 'actuation_known_geometry');

%% Step 1-2  derive and certify the base parameters
mdh = mdh_ur5e();
rf = fullfile(root, 'results', mdh.name, folder_of.(variant));
if ~isfile(fullfile(rf, 'base_regressor.mat'))                     % first time: run the pipeline (1-4 min)
    out = base_parameters_from_mdh(mdh, struct('variants', {{variant}}));
    disp(struct2table(out.table));
end
S = load(fullfile(rf, 'base_regressor.mat'), 'theta_base', 'A_matrix_base');
nb = numel(S.theta_base);
fprintf('\n%d base parameters of the UR5e (%s):\n', nb, variant);
for k = 1:nb, fprintf('%3d  %s\n', k, char(S.theta_base(k))); end

%% Step 3  numerical values of the base parameters from standard (CAD) parameters
[names, values] = nominal_parameters_ur5e();                       % m_i, Lc_i, I_i (origin-referenced), dimensions
if strcmp(variant, 'actuation_known')                              % demo values for the actuation terms
    for i = 1:6
        names  = [names, {sprintf('Ia%d', i), sprintf('Fv%d', i), sprintf('Fc%d', i)}];
        values = [values, 0.05*i, 0.4 + 0.1*i, 0.2 + 0.05*i];
    end
end
vars = symvar(S.theta_base);
vals = zeros(1, numel(vars));
for j = 1:numel(vars)
    idx = find(strcmp(names, char(vars(j))), 1);
    if isempty(idx), error('No value for the symbol %s: add it to names/values.', char(vars(j))); end
    vals(j) = values(idx);
end
theta_nominal = double(subs(S.theta_base, vars, vals));
fprintf('\nNominal base parameters (first 8):\n');  disp(theta_nominal(1:8).');

%% Step 4  identification from data (least squares)
n = mdh.n;
q_s   = arrayfun(@(k) sym(sprintf('t%d',   k), 'real'), 1:n);
qd_s  = arrayfun(@(k) sym(sprintf('t%dd',  k), 'real'), 1:n);
qdd_s = arrayfun(@(k) sym(sprintf('t%ddd', k), 'real'), 1:n);
Afun = matlabFunction(S.A_matrix_base, 'Vars', {q_s, qd_s, qdd_s});   % A_b(q, qd, qdd), size n-by-nb

% --- demo data: random states and torques from the independent Newton-Euler reference ---------------------
rng(1, 'twister');
N = 400;
Q = -pi + 2*pi*rand(N, n);  QD = -2 + 4*rand(N, n);  QDD = -3 + 6*rand(N, n);
ref = mdh_rnea_reference(mdh);
Y = zeros(N*n, 1);
for k = 1:N, Y((k-1)*n + (1:n)) = ref(Q(k,:), QD(k,:), QDD(k,:), names, values).'; end
% ---------------------------------------------------------------------------------------------------------
% With measured data: Q, QD, QDD (N-by-6) and Y (6N-by-1, torques stacked per sample) must be in the MDH
% convention of robots/mdh_ur5e.m. For the manufacturer convention q_UR used by MATLAB's universalUR5e model:
%   q = S*q_UR + delta,  qd = S*qd_UR,  qdd = S*qdd_UR,  tau = S*tau_UR,
%   S = diag(1,1,1,-1,-1,-1),  delta = [0 pi/2 0 pi/2 0 0]'.
% Check your own robot's joint convention before using these.

W = zeros(N*n, nb);
for k = 1:N, W((k-1)*n + (1:n), :) = Afun(Q(k,:), QD(k,:), QDD(k,:)); end
fprintf('\nIdentification matrix: %d x %d, rank %d, condition number %.1f\n', size(W,1), size(W,2), rank(W), cond(W));
theta_hat = W \ Y;                                                 % ordinary least squares
fprintf('max |theta_hat - theta_nominal| = %.3e   (torque RMSE %.3e N m)\n', ...
    max(abs(theta_hat - theta_nominal)), sqrt(mean((W*theta_hat - Y).^2)));
